import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { PersonCells, PersonHeads } from '../../slots/defs/personRow';
import { usePeople, type Person } from '../people/people.slot';
import { personActionKey, useLastPersonAction } from '../people/personAction';
import { useUser } from '../session/useSession';

function MergeHeads() {
  return <th>Merge</th>;
}

// The picker of another person and the button that merges this person into them: a steward's only, never into the
// person themselves, and neither may be retired. The merged person's claims, names, patrons and pool memberships go to
// the other and their row leaves the list, so the whole sheet is re-read. A refusal shows on the person until the
// picker is changed or the next action on their row.
function MergeCells({ sheetId, personId }: { sheetId: string; user: string; personId: number }) {
  const people = usePeople(sheetId).data ?? [];
  const [chosen, setChosen] = useState('');
  const [user] = useUser();
  const queryClient = useQueryClient();
  const merge = useMutation({
    mutationKey: personActionKey(sheetId, personId),
    mutationFn: async (into: string) => {
      if (into === '') throw new Error('Choose a person to merge into');
      return postJson<Person>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${personId}/merge`, {
        into: Number(into),
        by: user ?? '',
      });
    },
    onSuccess: async () => {
      setChosen('');
      await queryClient.invalidateQueries({ queryKey: ['sheet', sheetId] });
    },
  });
  const last = useLastPersonAction(sheetId, personId, merge.submittedAt);
  const offered = people.filter((p) => p.id !== personId);

  return (
    <td>
      <select
        data-testid="person-merge-into"
        value={chosen}
        onChange={(e) => {
          setChosen(e.target.value);
          merge.reset();
        }}
      >
        <option value="">Merge into…</option>
        {offered.map((p) => (
          <option key={p.id} value={String(p.id)}>
            {p.name}
          </option>
        ))}
      </select>{' '}
      <button type="button" data-testid="person-merge" disabled={merge.isPending} onClick={() => merge.mutate(chosen)}>
        Merge
      </button>
      {merge.isError && last && (
        <span data-testid="person-error" role="alert">
          {merge.error.message}
        </span>
      )}
    </td>
  );
}

export const contributions = [
  PersonHeads.fill({ order: 57, Component: MergeHeads }),
  PersonCells.fill({ order: 57, Component: MergeCells }),
];
import { useMutationState } from '@tanstack/react-query';

/** The key every action on a person's row (a statement, a retirement) runs its mutation under, so the row shows
 *  one error at a time: the last action's. */
export const personActionKey = (sheetId: string, personId: number) => ['sheet', sheetId, 'person-action', personId] as const;

/** Whether the mutation (run under personActionKey) is the last action taken on the person's row: only that
 *  one's refusal shows, so the next action on the row removes the error of the one before. */
export function useLastPersonAction(sheetId: string, personId: number, submittedAt: number): boolean {
  const times = useMutationState({
    filters: { mutationKey: personActionKey(sheetId, personId) },
    select: (m) => m.state.submittedAt,
  });
  return submittedAt === Math.max(0, ...times);
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { PersonCells, PersonHeads } from '../../slots/defs/personRow';
import { peopleKey, usePeople, type Person } from '../people/people.slot';
import { personActionKey, useLastPersonAction } from '../people/personAction';
import { useUser } from '../session/useSession';

function RetireHeads() {
  return (
    <>
      <th>Retired</th>
      <th>Retired from</th>
      <th />
    </>
  );
}

// Whether the person is retired and from when, and the date and button that retire them (a blank date: the
// sheet's today). A person with a retirement date counts as retired at once, whatever the date. A refusal shows
// on the person until the next action on their row.
function RetireCells({ sheetId, personId }: { sheetId: string; user: string; personId: number }) {
  const person = usePeople(sheetId).data?.find((p) => p.id === personId);
  const [date, setDate] = useState('');
  const [user] = useUser();
  const queryClient = useQueryClient();
  const retire = useMutation({
    mutationKey: personActionKey(sheetId, personId),
    mutationFn: (from: string) =>
      postJson<Person>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${personId}/retire`, {
        date: from.trim(),
        by: user ?? '',
      }),
    onSuccess: async () => {
      setDate('');
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) });
    },
  });
  const last = useLastPersonAction(sheetId, personId, retire.submittedAt);
  const retired = person?.retiredFrom != null;

  return (
    <>
      <td data-testid="person-retired">{retired ? 'yes' : 'no'}</td>
      <td data-testid="person-retired-from">{person?.retiredFrom ?? ''}</td>
      <td>
        <input
          type="date"
          data-testid="person-retire-date"
          value={date}
          onChange={(e) => {
            setDate(e.target.value);
            retire.reset();
          }}
        />{' '}
        <button type="button" data-testid="person-retire" disabled={retire.isPending} onClick={() => retire.mutate(date)}>
          Retire
        </button>
        {retire.isError && last && (
          <span data-testid="person-error" role="alert">
            {retire.error.message}
          </span>
        )}
      </td>
    </>
  );
}

export const contributions = [
  PersonHeads.fill({ order: 40, Component: RetireHeads }),
  PersonCells.fill({ order: 40, Component: RetireCells }),
];
import { defineSlot } from '../Slot';

/**
 * Extra columns of the people table. A contribution renders one `<th>` in the header slot and one
 * `<td>` per person in the cells slot, at the same order, so the columns line up.
 */
export const PersonHeads = defineSlot<{ sheetId: string; user: string }>('person.heads');
export const PersonCells = defineSlot<{ sheetId: string; user: string; personId: number }>('person.cells');
import { register } from './registry';
import type { Registered } from './registry';

// Discovery: every `features/**/*.slot.tsx` in the app is found here and registered, so there is
// no explicit list of features. A file exports `contribution`, or `contributions` for more than
// one. Imported once for its side effect by main.tsx.
const modules = import.meta.glob('../features/**/*.slot.tsx', { eager: true }) as Record<
  string,
  { contribution?: Omit<Registered, 'from' | 'order'> & { order?: number }; contributions?: Array<Omit<Registered, 'from' | 'order'> & { order?: number }> }
>;

for (const [from, mod] of Object.entries(modules)) {
  const declared = mod.contributions ?? (mod.contribution ? [mod.contribution] : []);
  for (const c of declared) {
    register({ ...c, from, order: c.order ?? 0 });
  }
}

