// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
/** A refused request: the reason, and the HTTP status (409: someone else saved the record first). */
export class HttpError extends Error {
  constructor(message: string, readonly status: number) {
    super(message);
  }
}

// The date the signed-in user's screen shows the sheet as of (none: as it stands now). Every request carries
// it as `asof`: a read answers as the sheet stood at the end of that date, and a change is refused while it is set.
// It belongs to this screen only, so it is kept here and in the URL (search param `asof`), never in the store.
let viewAsOf = new URLSearchParams(window.location.search).get('asof') ?? '';

export function getViewAsOf(): string {
  return viewAsOf;
}

export function setViewAsOf(date: string): void {
  viewAsOf = date;
}

async function send<T>(path: string, init?: RequestInit): Promise<T> {
  const url = viewAsOf === '' ? path : `${path}${path.includes('?') ? '&' : '?'}asof=${encodeURIComponent(viewAsOf)}`;
  const res = await fetch(url, init);
  if (!res.ok) {
    // A refusal carries {"error": "<why>"}; show that, else the status line.
    const body = (await res.json().catch(() => null)) as { error?: string } | null;
    throw new HttpError(body?.error ?? `${init?.method ?? 'GET'} ${path} -> ${res.status}`, res.status);
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

export function getJson<T>(path: string): Promise<T> {
  return send<T>(path);
}

export function postJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}

export function putJson<T>(path: string, body?: unknown): Promise<T> {
  return send<T>(path, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
}
import { useState } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { setViewAsOf } from '../../api/http';
import { SheetBody } from '../../slots/defs/sheetBody';
import { asString, useSearchParam } from '../../url/useSearchParam';

// The as-of date of this user's screen: while it is set, every panel shows the sheet as it stood at the end of that
// date (the date standing in for the sheet's today) and every change is refused. Setting or clearing it re-reads the
// whole sheet. It lives in the URL (search param `asof`), so it outlives loading another sheet; other users' screens
// are not affected.
function AsOfPanel({ sheetId }: { sheetId: string; user: string }) {
  const [asOf, setAsOf] = useSearchParam('asof', asString);
  const [input, setInput] = useState('');
  const [error, setError] = useState('');
  const queryClient = useQueryClient();

  const show = async (date: string) => {
    setViewAsOf(date);
    setAsOf(date);
    await queryClient.resetQueries({ queryKey: ['sheet', sheetId] });
  };

  return (
    <section data-testid="asof-panel">
      <form
        onSubmit={(e) => {
          e.preventDefault();
          const date = input.trim();
          if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) {
            setError('Enter a date');
            return;
          }
          setError('');
          void show(date);
        }}
      >
        As of: <strong data-testid="sheet-asof">{asOf}</strong>{' '}
        <input
          type="date"
          data-testid="asof-date"
          value={input}
          onChange={(e) => {
            setInput(e.target.value);
            setError('');
          }}
        />{' '}
        <button type="submit" data-testid="asof-set">
          Show as of
        </button>{' '}
        <button
          type="button"
          data-testid="asof-clear"
          onClick={() => {
            setError('');
            void show('');
          }}
        >
          Clear
        </button>
      </form>
